package com.causalops.demo;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.util.*;
@SpringBootApplication @RestController public class DemoApplication {final RestClient http=RestClient.create();static volatile int latency=0;public static void main(String[]x){SpringApplication.run(DemoApplication.class,x);}@GetMapping("/orders/{id}") Object order(@PathVariable String id)throws Exception{delay();return http.get().uri(System.getenv().getOrDefault("ORDER_URL","http://order-service:8080")+"/orders/"+id).retrieve().body(Map.class);}@PostMapping("/internal/fault") Object fault(@RequestBody Map<String,Object>x){latency=((Number)x.getOrDefault("latencyMs",0)).intValue();return Map.of("latencyMs",latency);}@GetMapping("/business") Object business()throws Exception{return order("demo");}void delay()throws Exception{if(latency>0)Thread.sleep(latency);}}
